const hexes = [
  "00000006000600104368e1bba963204ec4836e6720566970000f4dc3a3207175c3a02074e1bab76e67000746616e706167650012517579e1bb816e205269c3aa6e672054c6b0000bc490e1bb95692054c3aa6e001742e1baa36f2076e1bb872074c3a069206b686fe1baa36e",
  "000000010007000943616f207468e1bba7000e546f7020c491e1baa169206769610013c490e1baa16920676961206cc6b0e1bba36e67001543616f205468e1bba7205469e1babf6e204cc3aa6e001043616f205468e1bba7205068e1bb8f6d001543616f205468e1bba7204b696d2043c6b0c6a16e67001343616f205468e1bba72042e1baa77520437561",
  "000000020003001243616f205468e1bba72043c3a2752043c3a100185468c3a06e682054c3ad63682042e1baa36e205468c3a26e001c4e67c6b02064c3a26e206368c4836d206368e1bb89207475e1baa76e",
  ""
];
for(const hex of hexes) {
  const buf = Buffer.from(hex, 'hex');
  let offset = 0;
  function readInt() { const v = buf.readInt32BE(offset); offset+=4; return v; }
  function readShort() { const v = buf.readInt16BE(offset); offset+=2; return v; }
  function readUTF() { const len = readShort(); const str = buf.toString('utf8', offset, offset+len); offset+=len; return str; }
  console.log("ID =", readInt());
  const size = readShort();
  console.log("Size =", size);
  for(let i=0; i<size; i++) {
    console.log("  Option", i, ":", readUTF());
  }
}
